schemas.source:
overstory-schema-version = 1
; Nested maps are closed unless they declare * tstr => any.
meta = { ? title: tstr, * tstr => any }
point = { x: number, y: number }
row = {
  id: tstr,
  meta: meta,
  ? point: point,
  ? loose: { * text => any, },
  * tstr => any
}

overstory-schema-version = 1
overstory-primary-key = ["code"]
row = { code: tstr, count: number }

overstory-schema-version = 1
overstory-primary-key = ["rank", "id"]
row = { rank: int, id: tstr, title: tstr }

overstory-schema-version = 1
item = { a: tstr }
row = item

overstory-schema-version = 1
a = { x: a }
row = { y: tstr }

overstory-schema-version = 1
row = { x: a }
a = { y: b }
b = [* a]

overstory-schema-version = 1
tstr = int
row = { a: tstr }

overstory-schema-version = 1
pair<T> = [* T]
row = { a: tstr }

overstory-schema-version = 1
g = ( a: int )
row = { b: tstr }

overstory-schema-version = 1
g = { b: int }
row = { a: ~g }

overstory-schema-version = 1
g = { b: int }
row = { a: &g }

overstory-schema-version = 1
overstory-primary-key = ["nope"]
row = { id: tstr, ? opt: tstr, nul: tstr / null, obj: { a: int }, count: int }

overstory-schema-version = 1
overstory-primary-key = ["opt"]
row = { id: tstr, ? opt: tstr, nul: tstr / null, obj: { a: int }, count: int }

overstory-schema-version = 1
overstory-primary-key = ["nul"]
row = { id: tstr, ? opt: tstr, nul: tstr / null, obj: { a: int }, count: int }

overstory-schema-version = 1
overstory-primary-key = ["obj"]
row = { id: tstr, ? opt: tstr, nul: tstr / null, obj: { a: int }, count: int }

overstory-schema-version = 1
overstory-primary-key = ["id", "id"]
row = { id: tstr, ? opt: tstr, nul: tstr / null, obj: { a: int }, count: int }

overstory-schema-version = 1
overstory-primary-key = []
row = { id: tstr, ? opt: tstr, nul: tstr / null, obj: { a: int }, count: int }

overstory-schema-version = 1
overstory-child-name = "nope"
row = { id: tstr, ? opt: tstr, count: int, mixed: tstr / int }

overstory-schema-version = 1
overstory-child-name = "opt"
row = { id: tstr, ? opt: tstr, count: int, mixed: tstr / int }

overstory-schema-version = 1
overstory-child-name = "count"
row = { id: tstr, ? opt: tstr, count: int, mixed: tstr / int }

overstory-schema-version = 1
overstory-child-name = "mixed"
row = { id: tstr, ? opt: tstr, count: int, mixed: tstr / int }

overstory-schema-version = 1
overstory-child-name = id
row = { id: tstr, ? opt: tstr, count: int, mixed: tstr / int }
